-- The challenges for 2026-09-25: Making Peace with Money and Getting Better at
-- Asking for Help. Generated from data/challenges.json by
-- tools/challenges_sql.py --since 2026-09-25; an upsert on slug.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('making-peace-with-money', 'Making Peace with Money', 'For anyone who avoids looking at their money and feels the dread anyway. Each day is one small, calm step toward knowing where things stand, so money takes up less room in your head.', 'Money', 365, array['Money', 'Stress']::text[], 1, '2026-09-25T17:00:00+00:00'::timestamptz),
  ('getting-better-at-asking-for-help', 'Getting Better at Asking for Help', 'For people who carry everything alone because asking feels like a burden or a weakness. Each day is one small practice in asking, so help becomes something you can reach for before you are running on empty.', 'Communication', 365, array['Communication', 'Assertiveness']::text[], 1, '2026-09-25T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('making-peace-with-money', 'getting-better-at-asking-for-help');

